#!/usr/bin/env node
// Generic Slack Web API caller (Node.js >= 18; uses global fetch, no dependencies).
//
// Usage:
//   node slack_request.mjs <api.method> ['<json-payload>']
//
// Examples:
//   node slack_request.mjs api.test '{}'
//   node slack_request.mjs chat.postMessage '{"channel":"general","text":"Hello"}'
//   node slack_request.mjs conversations.history '{"channel":"C123","limit":10}'
//
// Reads the token from the SLACK_TOKEN environment variable.
// Output is LLM-friendly: concise errors on stderr, truncated JSON on stdout.
// Raise the output cap with SLACK_OUTPUT_MAX (default 4000 chars).

const method = process.argv[2];
const rawPayload = process.argv[3] || "{}";
const maxChars = Number(process.env.SLACK_OUTPUT_MAX || 4000);

function usage() {
  console.error("Usage: node slack_request.mjs <api.method> ['<json-payload>']");
  console.error('Example: node slack_request.mjs chat.postMessage \'{"channel":"general","text":"Hello"}\'');
}

if (!method || !/^[a-z]+\.[a-zA-Z0-9_]+$/.test(method)) {
  usage();
  process.exit(2);
}

const token = process.env.SLACK_TOKEN;
if (!token) {
  console.error("Error: SLACK_TOKEN environment variable is not set. Ask the user to export it (e.g. export SLACK_TOKEN=xoxb-...).");
  process.exit(2);
}

let payload;
try {
  payload = JSON.parse(rawPayload);
} catch {
  console.error(`Error: payload is not valid JSON: ${rawPayload}`);
  process.exit(2);
}

const url = `https://slack.com/api/${method}`;

async function main() {
  let res;
  try {
    res = await fetch(url, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json; charset=utf-8",
      },
      body: JSON.stringify(payload),
    });
  } catch (err) {
    console.error(`Error: request failed: ${err.message}`);
    process.exit(1);
  }

  if (res.status === 429) {
    const retryAfter = res.headers.get("retry-after") || "unknown";
    console.error(`Error: rate limited (HTTP 429). Retry after ${retryAfter} seconds.`);
    process.exit(1);
  }

  const text = await res.text();
  let json;
  try {
    json = JSON.parse(text);
  } catch {
    console.error(`Error: HTTP ${res.status} returned a non-JSON response.`);
    process.exit(1);
  }

  if (!json.ok) {
    const parts = [`Slack error: ${json.error}`];
    if (json.needed) parts.push(`missing scope(s): ${json.needed}`);
    if (json.provided) parts.push(`token provides: ${json.provided}`);
    console.error(`Error: ${parts.join(" | ")}`);
    process.exit(1);
  }

  const out = JSON.stringify(json, null, 2);
  if (out.length > maxChars) {
    console.log(out.slice(0, maxChars));
    console.log(`\n[output truncated: ${out.length} total chars; raise with SLACK_OUTPUT_MAX]`);
  } else {
    console.log(out);
  }

  const nextCursor = json?.response_metadata?.next_cursor;
  if (nextCursor) {
    console.log(`\nPagination: next_cursor present. Call again with "cursor":"${nextCursor}" to fetch more.`);
  }
}

main().catch((err) => {
  console.error(`Unexpected error: ${err.message}`);
  process.exit(1);
});
